def prepare(self, **options):
    from Cheetah.Template import Template
    self.context = threading.local()
    self.context.vars = {}
    options['searchList'] = [self.context.vars]
    if self.source:
        self.tpl = Template(source=self.source, **options)
    else:
        self.tpl = Template(file=self.filename, **options)

def prepare(self, filters=None, tests=None, globals={}, **kwargs):
    from jinja2 import Environment, FunctionLoader
    self.env = Environment(loader=FunctionLoader(self.loader), **kwargs)
    if filters: self.env.filters.update(filters)
    if tests: self.env.tests.update(tests)
    if globals: self.env.globals.update(globals)
    if self.source:
        self.tpl = self.env.from_string(self.source)
    else:
        self.tpl = self.env.get_template(self.name)

def render(self, *args, **kwargs):
    for dictarg in args:
        kwargs.update(dictarg)
    _defaults = self.defaults.copy()
    _defaults.update(kwargs)
    return self.tpl.render(**_defaults)

def loader(self, name):
    if name == self.filename:
        fname = name
    else:
        fname = self.search(name, self.lookup)
    if not fname: return
    with open(fname, "rb") as f:
        return (f.read().decode(self.encoding), fname, lambda: False)

@cached_property
def co(self):
    return compile(self.code, self.filename or '<string>', 'exec')

@cached_property
def code(self):
    source = self.source
    if not source:
        with open(self.filename, 'rb') as f:
            source = f.read()
    try:
        source, encoding = touni(source), 'utf8'
    except UnicodeError:
        raise depr(0, 11, 'Unsupported template encodings.', 'Use utf-8 for templates.')
    parser = StplParser(source, encoding=encoding, syntax=self.syntax)
    code = parser.translate()
    self.encoding = parser.encoding
    return code

def _include(self, _env, _name=None, **kwargs):
    env = _env.copy()
    env.update(kwargs)
    if _name not in self.cache:
        self.cache[_name] = self.__class__(name=_name, lookup=self.lookup, syntax=self.syntax)
    return self.cache[_name].execute(env['_stdout'], env)

def render(self, *args, **kwargs):
    """ Render the template using keyword arguments as local variables. """
    env = {}
    stdout = []
    for dictarg in args:
        env.update(dictarg)
    env.update(kwargs)
    self.execute(stdout, env)
    return ''.join(stdout)

def get_syntax(self):
    """ Tokens as a space separated string (default: <% %> % {{ }}) """
    return self._syntax

@staticmethod
def process_inline(chunk):
    if chunk[0] == '!': return '_str(%s)' % chunk[1:]
    return '_escape(%s)' % chunk

def template(*args, **kwargs):
    """
    Get a rendered template as a string iterator.
    You can use a name, a filename or a template string as first parameter.
    Template rendering arguments can be passed as dictionaries
    or directly (as keyword arguments).
    """
    tpl = args[0] if args else None
    for dictarg in args[1:]:
        kwargs.update(dictarg)
    adapter = kwargs.pop('template_adapter', SimpleTemplate)
    lookup = kwargs.pop('template_lookup', TEMPLATE_PATH)
    tplid = (id(lookup), tpl)
    if tplid not in TEMPLATES or DEBUG:
        settings = kwargs.pop('template_settings', {})
        if isinstance(tpl, adapter):
            TEMPLATES[tplid] = tpl
            if settings: TEMPLATES[tplid].prepare(**settings)
        elif "\n" in tpl or "{" in tpl or "%" in tpl or '$' in tpl:
            TEMPLATES[tplid] = adapter(source=tpl, lookup=lookup, **settings)
        else:
            TEMPLATES[tplid] = adapter(name=tpl, lookup=lookup, **settings)
    if not TEMPLATES[tplid]:
        abort(500, 'Template (%s) not found' % tpl)
    return TEMPLATES[tplid].render(kwargs)

def view(tpl_name, **defaults):
    """ Decorator: renders a template for a handler.
        The handler can control its behavior like that:

          - return a dict of template vars to fill out the template
          - return something other than a dict and the view decorator will not
            process the template, but return the handler result as is.
            This includes returning a HTTPResponse(dict) to get,
            for instance, JSON with autojson or other castfilters.
    """

    def decorator(func):

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            if isinstance(result, (dict, DictMixin)):
                tplvars = defaults.copy()
                tplvars.update(result)
                return template(tpl_name, **tplvars)
            elif result is None:
                return template(tpl_name, **defaults)
            return result

        return wrapper

    return decorator

def decorator(func):

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        if isinstance(result, (dict, DictMixin)):
            tplvars = defaults.copy()
            tplvars.update(result)
            return template(tpl_name, **tplvars)
        elif result is None:
            return template(tpl_name, **defaults)
        return result

    return wrapper

@functools.wraps(func)
def wrapper(*args, **kwargs):
    result = func(*args, **kwargs)
    if isinstance(result, (dict, DictMixin)):
        tplvars = defaults.copy()
        tplvars.update(result)
        return template(tpl_name, **tplvars)
    elif result is None:
        return template(tpl_name, **defaults)
    return result

def _main(argv):  # pragma: no coverage
    args, parser = _cli_parse(argv)

    def _cli_error(cli_msg):
        parser.print_help()
        _stderr('\nError: %s\n' % cli_msg)
        sys.exit(1)

    if args.version:
        print(__version__)
        sys.exit(0)
    if not args.app:
        _cli_error("No application entry point specified.")

    sys.path.insert(0, '.')
    sys.modules.setdefault('bottle', sys.modules['__main__'])

    host, port = (args.bind or 'localhost'), 8080
    if ':' in host and host.rfind(']') < host.rfind(':'):
        host, port = host.rsplit(':', 1)
    host = host.strip('[]')

    config = ConfigDict()

    for cfile in args.conf or []:
        try:
            if cfile.endswith('.json'):
                with open(cfile, 'rb') as fp:
                    config.load_dict(json_loads(fp.read()))
            else:
                config.load_config(cfile)
        except configparser.Error as parse_error:
            _cli_error(parse_error)
        except IOError:
            _cli_error("Unable to read config file %r" % cfile)
        except (UnicodeError, TypeError, ValueError) as error:
            _cli_error("Unable to parse config file %r: %s" % (cfile, error))

    for cval in args.param or []:
        if '=' in cval:
            config.update((cval.split('=', 1),))
        else:
            config[cval] = True

    run(args.app,
        host=host,
        port=int(port),
        server=args.server,
        reloader=args.reload,
        plugins=args.plugin,
        debug=args.debug,
        config=config)

