    except AttributeError:
        pass

def depr(major, minor, cause, fix, stacklevel=3):
    text = "Use of feature or API deprecated since Bottle-%d.%d\n"\
        "Cause: %s\n"\
        "Fix: %s\n" % (major, minor, cause, fix)
    if DEBUG == 'strict':
        raise DeprecationWarning(text)
    warnings.warn(text, DeprecationWarning, stacklevel=stacklevel)
    return DeprecationWarning(text)

def makelist(data):  # This is just too handy
    if isinstance(data, (tuple, list, set, dict)):
        return list(data)
    elif data:
        return [data]
    else:
        return []

def __get__(self, obj, cls):
    if obj is None: return self
    key, storage = self.key, getattr(obj, self.attr)
    if key not in storage: storage[key] = self.getter(obj)
    return storage[key]

def __set__(self, obj, value):
    if self.read_only: raise AttributeError("Read-Only property.")
    getattr(obj, self.attr)[self.key] = value

def __delete__(self, obj):
    if self.read_only: raise AttributeError("Read-Only property.")
    del getattr(obj, self.attr)[self.key]

def __init__(self, func):
    update_wrapper(self, func)
    self.func = func

def __init__(self, func):
    functools.update_wrapper(self, func, updated=[])
    self.getter = func

def add(self, rule, method, target, name=None):
    """ Add a new rule or replace the target for an existing rule. """
    anons = 0  # Number of anonymous wildcards found
    keys = []  # Names of keys
    pattern = ''  # Regular expression pattern with named groups
    filters = []  # Lists of wildcard input filters
    builder = []  # Data structure for the URL builder
    is_static = True

    for key, mode, conf in self._itertokens(rule):
        if mode:
            is_static = False
            if mode == 'default': mode = self.default_filter
            mask, in_filter, out_filter = self.filters[mode](conf)
            if not key:
                pattern += '(?:%s)' % mask
                key = 'anon%d' % anons
                anons += 1
            else:
                pattern += '(?P<%s>%s)' % (key, mask)
                keys.append(key)
            if in_filter: filters.append((key, in_filter))
            builder.append((key, out_filter or str))
        elif key:
            pattern += re.escape(key)
            builder.append((None, key))

    self.builder[rule] = builder
    if name: self.builder[name] = builder

    if is_static and not self.strict_order:
        self.static.setdefault(method, {})
        self.static[method][self.build(rule)] = (target, None)
        return

    try:
        re_pattern = re.compile('^(%s)$' % pattern)
        re_match = re_pattern.match
    except re.error as e:
        raise RouteSyntaxError("Could not add Route: %s (%s)" % (rule, e))

    if filters:

        def getargs(path):
            url_args = re_match(path).groupdict()
            for name, wildcard_filter in filters:
                try:
                    url_args[name] = wildcard_filter(url_args[name])
                except ValueError:
                    raise HTTPError(400, 'Path has wrong format.')
            return url_args
    elif re_pattern.groupindex:

        def getargs(path):
            return re_match(path).groupdict()
    else:
        getargs = None

    flatpat = _re_flatten(pattern)
    whole_rule = (rule, flatpat, target, getargs)

    if (flatpat, method) in self._groups:
        if DEBUG:
            msg = 'Route <%s %s> overwrites a previously defined route'
            warnings.warn(msg % (method, rule), RuntimeWarning, stacklevel=3)
        self.dyna_routes[method][
            self._groups[flatpat, method]] = whole_rule
    else:
        self.dyna_routes.setdefault(method, []).append(whole_rule)
        self._groups[flatpat, method] = len(self.dyna_routes[method]) - 1

    self._compile(method)

def getargs(path):
    url_args = re_match(path).groupdict()
    for name, wildcard_filter in filters:
        try:
            url_args[name] = wildcard_filter(url_args[name])
        except ValueError:
            raise HTTPError(400, 'Path has wrong format.')
    return url_args

def build(self, _name, *anons, **query):
    """ Build an URL by filling the wildcards in a rule. """
    builder = self.builder.get(_name)
    if not builder:
        raise RouteBuildError("No route with that name.", _name)
    try:
        for i, value in enumerate(anons):
            query['anon%d' % i] = value
        url = ''.join([f(query.pop(n)) if n else f for (n, f) in builder])
        return url if not query else url + '?' + urlencode(query, doseq=True)
    except KeyError as E:
        raise RouteBuildError('Missing URL argument: %r' % E.args[0])

def match(self, environ):
    """ Return a (target, url_args) tuple or raise HTTPError(400/404/405). """
    verb = environ['REQUEST_METHOD'].upper()
    path = environ['PATH_INFO'] or '/'

    methods = ('PROXY', 'HEAD', 'GET', 'ANY') if verb == 'HEAD' else ('PROXY', verb, 'ANY')

    for method in methods:
        if method in self.static and path in self.static[method]:
            target, getargs = self.static[method][path]
            return target, getargs(path) if getargs else {}
        elif method in self.dyna_regexes:
            for combined, rules in self.dyna_regexes[method]:
                match = combined(path)
                if match:
                    target, getargs = rules[match.lastindex - 1]
                    return target, getargs(path) if getargs else {}

    # No matching route found. Collect alternative methods for 405 response
    allowed = set([])
    nocheck = set(methods)
    for method in set(self.static) - nocheck:
        if path in self.static[method]:
            allowed.add(method)
    for method in set(self.dyna_regexes) - allowed - nocheck:
        for combined, rules in self.dyna_regexes[method]:
            match = combined(path)
            if match:
                allowed.add(method)
    if allowed:
        allow_header = ",".join(sorted(allowed))
        raise HTTPError(405, "Method not allowed.", Allow=allow_header)

    # No matching route and no alternative method found. We give up
    raise HTTPError(404, "Not found: " + repr(path))

def prepare(self):
    """ Do all on-demand work immediately (useful for debugging)."""
    self.call

def all_plugins(self):
    """ Yield all Plugins affecting this route. """
    unique = set()
    for p in reversed(self.app.plugins + self.plugins):
        if True in self.skiplist: break
        name = getattr(p, 'name', False)
        if name and (name in self.skiplist or name in unique): continue
        if p in self.skiplist or type(p) in self.skiplist: continue
        if name: unique.add(name)
        yield p

def _make_callback(self):
    callback = self.callback
    for plugin in self.all_plugins():
        if hasattr(plugin, 'apply'):
            callback = plugin.apply(callback, self)
        else:
            callback = plugin(callback)
        if callback is not self.callback:
            update_wrapper(callback, self.callback)
    return callback

def __repr__(self):
    cb = self.get_undecorated_callback()
    return '<%s %s -> %s:%s>' % (
        self.method, self.rule, cb.__module__, getattr(cb, '__name__', '?')
    )

