    try:
        del self.environ['bottle.request.ext.%s' % name]
    except KeyError:
        raise AttributeError("Attribute not defined: %s" % name)

def _hkey(key):
    key = touni(key)
    return key.title().replace('_', '-')

def _hval(value):
    value = touni(value)
    return value

