    """ The HTTP status code as an integer (e.g. 404)."""
    return self._status_code

def _set_status(self, status):
    if isinstance(status, int):
        code, status = status, _HTTP_STATUS_LINES.get(status)
    elif ' ' in status:
        if '\n' in status or '\r' in status or '\0' in status:
            raise ValueError('Status line must not include control chars.')
        status = status.strip()
        code = int(status.split()[0])
    else:
        raise ValueError('String status line without a reason phrase.')
    if not 100 <= code <= 999:
        raise ValueError('Status code out of range.')
    self._status_code = code
    self._status_line = str(status or ('%d Unknown' % code))

def add_header(self, name, value):
    """ Add an additional response header, not removing duplicates. """
    self._headers.setdefault(_hkey(name), []).append(_hval(value))

def _wsgi_status_line(self):
    """ WSGI conform status line (latin1-encodeable) """
    return self._status_line.encode('utf8', 'surrogateescape').decode('latin1')

@property
def headerlist(self):
    """ WSGI conform list of (header, value) tuples. """
    out = []
    headers = list(self._headers.items())
    if 'Content-Type' not in self._headers:
        headers.append(('Content-Type', [self.default_content_type]))
    if self._status_code in self.bad_headers:
        bad_headers = self.bad_headers[self._status_code]
        headers = [h for h in headers if h[0] not in bad_headers]
    out += [(name, val) for (name, vals) in headers for val in vals]
    if self._cookies:
        for c in self._cookies.values():
            out.append(('Set-Cookie', _hval(c.OutputString())))
    out = [(k, v.encode('utf8', 'surrogateescape').decode('latin1')) for (k, v) in out]
    return out

@property
def charset(self, default='UTF-8'):
    """ Return the charset specified in the content-type header (default: utf8). """
    if 'charset=' in self.content_type:
        return self.content_type.split('charset=')[-1].split(';')[0].strip()
    return default

def __repr__(self):
    out = ''
    for name, value in self.headerlist:
        out += '%s: %s\n' % (name.title(), value.strip())
    return out

def _local_property():
    ls = threading.local()

    def fget(_):
        try:
            return ls.var
        except AttributeError:
            raise RuntimeError("Request context not initialized.")

    def fset(_, value):
        ls.var = value

    def fdel(_):
        del ls.var

    return property(fget, fset, fdel, 'Thread-local property')

def fget(_):
    try:
        return ls.var
    except AttributeError:
        raise RuntimeError("Request context not initialized.")

def apply(self, callback, route):
    dumps = self.json_dumps
    if not self.json_dumps: return callback

    @functools.wraps(callback)
    def wrapper(*a, **ka):
        try:
            rv = callback(*a, **ka)
        except HTTPResponse as resp:
            rv = resp

        if isinstance(rv, dict):
            # Attempt to serialize, raises exception on failure
            json_response = dumps(rv)
            # Set content type only if serialization successful
            response.content_type = 'application/json'
            return json_response
        elif isinstance(rv, HTTPResponse) and isinstance(rv.body, dict):
            rv.body = dumps(rv.body)
            rv.content_type = 'application/json'
        return rv

    return wrapper

